verus! {
    // Remove the first element of a non‐empty Vec<i32>,
    // producing a new Vec of length one less, preserving order.
    fn remove_front(a: &Vec<i32>) -> (b: Vec<i32>)
        requires
            a.len() > 0,
        ensures
            b.len() == a.len() - 1,
            forall|i: usize| i < b.len() ==> b[i] == a[i + 1],
    {
        let n = a.len();
        let mut b: Vec<i32> = Vec::new();
        let mut i: usize = 1;
        while i < n
            invariant
                // i ranges from 1 up to n
                1 <= i <= n,
                // b has accumulated exactly i−1 elements
                b.len() == i - 1,
                // and those elements match a[1..i]
                forall|j: usize| j < b.len() ==> b[j] == a[j + 1],
            decreases n - i,
        {
            b.push(a[i]);
            i = i + 1;
        }
        b
    }
}

